            "eligibilityUrl": "https://www.sos.alabama.gov/alabama-votes/voter/absentee-voting",
            "returnInPersonUrl": "https://www.sos.alabama.gov/alabama-votes/voter/absentee-voting",
            "excuseRequired": true,
            "excuses": [
              {
